G=load()

def solve(A):
    H=len(A); W=len(A[0])
    nz=[(i,j,A[i][j]) for i in range(H) for j in range(W) if i==j and A[i][j]!=0]
    # use main diag nonzero values
    diags=[(i,A[i][i]) for i in range(min(H,W)) if A[i][i]!=0]
    s=[v for _,v in diags]; k=len(s)
    def fmax(i,j): return max(i,j)
    def fmin(i,j): return min(i,j)
    fm = fmax if all(A[i][j]==s[max(i,j)%k] for i in range(H) for j in range(W)) else fmin
