def get_diag(A):
    nz=A!=0; rs=np.where(nz.any(1))[0]; cs=np.where(nz.any(0))[0]
    sub=A[rs.min():rs.max()+1, cs.min():cs.max()+1]
    return [int(sub[i,i]) for i in range(sub.shape[0])], int(sub.shape[0])

def fit_quad(Q,S,m,N):
    # find (formula, coeffs) fitting Q[a,b]=S[(expr)%m] uniformly
    res=[]
    def try_expr(name,a_coeff,b_coeff,const_val):
        ok=True
        for a in range(N):
            for b in range(N):
                val=(a_coeff*a+b_coeff*b+const_val)%m
                if Q[a,b]!=S[val]: ok=False;break
            if not ok:break
        if ok: res.append((name,a_coeff,b_coeff,const_val))
    for ac in (-1,0,1):
        for bc in (-1,0,1):
            for cv in range(m):
                try_expr('lin',ac,bc,cv)
    return res

for nm,I,O in [('demo4',I4,O4),('demo5',I5,O5),('demo6',I6,O6)]:
    D,m=get_diag(I)[0],get_diag(I)[1]
    N=O.shape[0]//2
    print(nm,'m',m,'N',N)
    for q,(ir,jc) in [('tl',(0,0)),('tr',(0,N)),('bl',(N,0)),('br',(N,N))]:
        Q=O[ir*N:ir*N+N, jc*N:jc*N+N]
        r=fit_quad(Q,D,m,N)
        print(' ',q,r[:8],'...' if len(r)>8 else '')

