def pad(T,Q):
    hh,ww=T.shape; qh,qw=Q.shape
    R=np.zeros_like(Q)
    R[:hh,:ww]=T
    for r in range(hh,qh): R[r,:ww]=R[hh-1,:ww]
    for c in range(ww,qw): R[:hh,c]=R[:hh,ww-1]
    return R

